<script setup>
import {ref,reactive,computed,onMounted,watch} from 'vue'
import SrmModal from '../srm-ui/SrmModal.vue'
const props=defineProps({api:Function,context:Object,supplier:Object,categories:{type:Array,default:()=>[]}}),emit=defineEmits(['changed','inspect'])
const fields={name:'供应商名称',category:'品类',creditCode:'信用代码',bankAccount:'银行账号',bankName:'开户行',address:'注册地址'}
const kinds={ONBOARD:'准入申请',CHANGE:'关键资料变更',FREEZE:'冻结申请',UNFREEZE:'解冻申请',ELIMINATE:'淘汰申请'},states={PENDING:'待审核',APPROVED:'已通过',REJECTED:'已驳回',RETURNED:'已退回补正',WITHDRAWN:'已撤回'}
const actions={CLAIM:'领取',APPROVE:'同意',REJECT:'驳回',RETURN:'退回补正',TRANSFER:'转办',ADD_SIGN:'加签',WITHDRAW:'撤回'}
const list=ref([]),tasks=ref([]),definitions=ref([]),selected=ref(null),error=ref(''),busy=ref(false),modal=ref(''),kind=ref('ONBOARD'),comment=ref(''),target=ref(''),candidates=ref([]),activeTask=ref(null),action=ref('APPROVE'),invitation=ref(''),versions=ref([])
const uploadKind=ref('ONBOARD'),uploadFile=ref(null)
const form=reactive({name:'',category:'',creditCode:'',bankAccount:'',bankName:'',address:'',reason:''})
const admin=computed(()=>!props.context.portal&&(props.context.roles.includes('superAdmin')||props.context.roles.includes('SYS-ADMIN')))
const canApply=computed(()=>props.supplier&&!['REVIEWING','ELIMINATED'].includes(props.supplier.status)&&!list.value.some(x=>x.status==='PENDING'))
async function load(){error.value='';try{if(props.supplier){list.value=await props.api('/suppliers/'+props.supplier.id+'/approvals');versions.value=await props.api('/suppliers/'+props.supplier.id+'/versions')}else{tasks.value=await props.api('/approvals/tasks');if(admin.value)definitions.value=await props.api('/workflow/definitions')}}catch(e){error.value=e.message}}
onMounted(load);watch(()=>props.supplier?.rowVersion,load)
function apply(k){kind.value=k;modal.value='apply';error.value='';Object.assign(form,{name:props.supplier.name,category:props.supplier.category,creditCode:'',bankAccount:'',bankName:props.supplier.bankName||'',address:props.supplier.address||'',reason:''})}
async function submit(){busy.value=true;error.value='';try{let changes;if(kind.value==='CHANGE'){changes={...form,rowVersion:props.supplier.rowVersion};delete changes.reason;if(!changes.creditCode)delete changes.creditCode;if(!changes.bankAccount)delete changes.bankAccount}selected.value=await props.api('/suppliers/'+props.supplier.id+'/approvals',{kind:kind.value,requestKey:crypto.randomUUID(),rowVersion:props.supplier.rowVersion,reason:form.reason,changes},'POST');modal.value='';await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
async function withdraw(){busy.value=true;error.value='';try{selected.value=await props.api('/approvals/'+selected.value.id+'/withdraw',{comment:comment.value},'POST');modal.value='';await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
async function show(id){error.value='';try{selected.value=await props.api('/approvals/'+id)}catch(e){error.value=e.message}}
async function prepare(t,a){activeTask.value=t;action.value=a;comment.value='';target.value='';error.value='';try{if(['TRANSFER','ADD_SIGN'].includes(a))candidates.value=await props.api('/approvals/'+selected.value.id+'/tasks/'+t.id+'/candidates');modal.value='decision'}catch(e){error.value=e.message}}
async function decide(){busy.value=true;error.value='';try{selected.value=await props.api('/approvals/'+selected.value.id+'/tasks/'+activeTask.value.id,{action:action.value,comment:comment.value,targetId:target.value||null},'POST');modal.value='';await load();emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
function myTask(t){if(props.context.portal||selected.value?.requestedBy===props.context.userId||selected.value?.status!=='PENDING')return false;return (!t.assignee||t.assignee===props.context.userId)&&(props.context.roles.includes('superAdmin')||props.context.roles.includes(t.node==='sqe'?'SQE':'CAT-MGR')||t.node==='ADD_SIGN'&&t.assignee===props.context.userId)}
async function publish(k){try{await props.api('/workflow/definitions',{kind:k},'POST');await load()}catch(e){error.value=e.message}}
async function upload(){try{if(!uploadFile.value)throw new Error('请选择BPMN文件');const data=new FormData();data.append('kind',uploadKind.value);data.append('file',uploadFile.value);await props.api('/workflow/definitions/upload',data,'POST');await load()}catch(e){error.value=e.message}}
async function exportXml(d){try{const blob=await props.api('/workflow/definitions/'+d.id+'/xml',undefined,'GET',true),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=d.key+'.bpmn20.xml';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){error.value=e.message}}
async function suspend(d){try{await props.api('/workflow/definitions/'+d.id+'/suspension',{suspended:!d.suspended},'POST');await load()}catch(e){error.value=e.message}}
async function invite(){try{const r=await props.api('/registration-invitations',{},'POST');invitation.value=r.invitation}catch(e){error.value=e.message}}
</script>
<template>
 <section class="lifecycle-panel">
  <p v-if="error&&!modal" class="form-error" role="alert">{{error}}</p>
  <template v-if="supplier">
   <div class="inline-actions" v-if="canApply"><button v-if="context.canManage&&['POTENTIAL','CORRECTION'].includes(supplier.status)" class="btn primary" @click="apply('ONBOARD')">提交准入</button><button v-if="context.canManage&&['QUALIFIED','FROZEN'].includes(supplier.status)" class="btn" @click="apply('CHANGE')">申请关键资料变更</button><button v-if="context.canClassify&&supplier.status==='QUALIFIED'" class="btn" @click="apply('FREEZE')">申请冻结</button><button v-if="context.canClassify&&supplier.status==='FROZEN'" class="btn" @click="apply('UNFREEZE')">申请解冻</button><button v-if="context.canClassify" class="btn" @click="apply('ELIMINATE')">申请淘汰</button></div>
   <div class="info-note">{{supplier.status==='CORRECTION'?'请按审核意见补齐资料后重新提交，流程从 SQE 节点重新开始。':'提交后档案和资质暂时锁定，防止审批依据发生变化。'}} 申请人与审批人分离。</div>
   <h3>审批与生命周期</h3><article v-for="l in list" :key="l.id" class="history-item"><button class="text-btn" @click="show(l.id)">{{kinds[l.kind]}} · {{states[l.status]}}</button><p>{{l.createdAt}}</p></article><p v-if="!list.length" class="muted">暂无审批申请</p>
   <h3 v-if="versions.length">资料版本追溯</h3><details v-for="v in versions" :key="v.version" class="history-item"><summary>版本 {{v.version}} · {{v.time}}</summary><table v-if="context.sensitive"><thead><tr><th>字段</th><th>变更前</th><th>变更后</th></tr></thead><tbody><tr v-for="(label,key) in fields" :key="key"><td>{{label}}</td><td>{{v.before[key]||'未填写'}}</td><td>{{v.after[key]||'未填写'}}</td></tr></tbody></table><p v-else class="muted">没有敏感字段查看权限</p></details>
  </template>
  <template v-else>
   <div class="panel-heading"><div><h2>我的审批待办</h2><p>按组织、角色、数据范围与任务归属筛选；不可审批本人申请。</p></div><button class="btn" @click="load">刷新待办</button></div>
   <div class="table-scroll"><table><thead><tr><th>供应商</th><th>业务类型</th><th>审批节点</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="t in tasks" :key="t.id"><td>{{t.supplierName}}<small style="display:block">{{t.supplierCode}}</small></td><td>{{kinds[t.kind]}}</td><td>{{t.name}}</td><td>{{t.createdAt}}</td><td><button class="text-btn" @click="show(t.approvalId)">查看并处理</button></td></tr></tbody></table><div v-if="!tasks.length" class="empty-state">当前没有需要你处理的审批</div></div>
   <div v-if="context.canManage" class="panel-heading"><div><h3>邀请供应商注册</h3><p>单次邀请，7天有效，注册档案归属你的组织。</p><p v-if="invitation" class="invitation-result">{{invitation}}</p></div><button class="btn" @click="invite">生成注册邀请</button></div>
   <template v-if="admin"><div class="panel-heading"><h3>流程版本与分类</h3><p>挂起版本停止新发起，已有申请继续处理。</p></div><div class="inline-actions"><button v-for="(label,k) in kinds" :key="k" class="btn" @click="publish(k)">发布{{label}}新版本</button></div><table><thead><tr><th>流程</th><th>版本</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="d in definitions" :key="d.id"><td>{{kinds[d.category]||d.key}}</td><td>v{{d.version}}</td><td>{{d.suspended?'已挂起':'可发起'}}</td><td><button class="text-btn" @click="exportXml(d)">下载 BPMN</button><button class="text-btn" @click="suspend(d)">{{d.suspended?'激活':'挂起'}}</button></td></tr></tbody></table><form class="inline-actions" @submit.prevent="upload"><select aria-label="上传流程分类" v-model="uploadKind"><option v-for="(label,k) in kinds" :key="k" :value="k">{{label}}</option></select><input aria-label="BPMN文件" type="file" accept=".xml,.bpmn" required @change="uploadFile=$event.target.files[0]" /><button class="btn">上传并发布版本</button></form><p class="info-note">可下载模板、修改节点名称后上传。保留业务节点与候选角色；禁止脚本、服务任务和任意表达式。</p></template>
  </template>
  <SrmModal v-if="selected&&!modal" :title="kinds[selected.kind]+' · '+states[selected.status]" @close="selected=null"><h3>{{selected.supplierName}}</h3><button class="text-btn" @click="emit('inspect',selected.supplierId);selected=null">查看供应商档案与资质</button><p>申请人 {{selected.requestedBy}}</p><button v-if="selected.status==='PENDING'&&(selected.requestedBy===context.userId||context.roles.includes('superAdmin'))" class="btn" @click="modal='withdraw';comment=''">撤回申请</button><p>申请原因：{{selected.reason||'首次准入'}}</p><details v-if="selected.kind==='CHANGE'"><summary>查看拟变更资料与原始资料</summary><table v-if="context.sensitive"><thead><tr><th>字段</th><th>当前有效资料</th><th>申请变更为</th></tr></thead><tbody><tr v-for="(label,key) in fields" :key="key"><td>{{label}}</td><td>{{selected.before[key]||'未填写'}}</td><td>{{selected.changes[key]??'保持原值'}}</td></tr></tbody></table><p v-else>没有敏感字段查看权限</p></details><article v-for="a in selected.actions" :key="a.id" class="history-item"><strong>{{actions[a.action]||a.action}} · {{a.actorId}}</strong><p>{{a.comment}}</p><small>{{a.time}}</small></article><article v-for="t in selected.tasks" :key="t.id" class="history-item"><h3>{{t.name}}</h3><p>{{t.assignee?'已分配审批人':'等待角色候选人处理'}}</p><div v-if="myTask(t)" class="inline-actions"><button class="btn primary" @click="prepare(t,'APPROVE')">同意</button><button class="btn" @click="prepare(t,'REJECT')">驳回</button><button v-if="t.node==='sqe'&&selected.kind==='ONBOARD'" class="btn" @click="prepare(t,'RETURN')">退回补正</button><template v-if="t.node!=='ADD_SIGN'"><button class="btn" @click="prepare(t,'CLAIM')">领取</button><button class="btn" @click="prepare(t,'TRANSFER')">转办</button><button class="btn" @click="prepare(t,'ADD_SIGN')">加签</button></template></div></article><p v-if="error" class="form-error">{{error}}</p></SrmModal>
  <SrmModal v-if="modal==='apply'" :title="kinds[kind]" @close="modal=''"><form @submit.prevent="submit"><template v-if="kind==='CHANGE'"><label>供应商名称<input v-model="form.name" required maxlength="128" /></label><label>品类<select v-model="form.category"><option v-for="c in categories" :key="c.code" :value="c.code">{{c.name}}</option></select></label><label>信用代码（留空保持原值）<input aria-label="变更信用代码" v-model="form.creditCode" maxlength="18" /></label><label>银行账号（留空保持原值）<input aria-label="变更银行账号" v-model="form.bankAccount" maxlength="64" /></label><label>开户行<input v-model="form.bankName" maxlength="64" /></label><label>地址<input v-model="form.address" maxlength="255" /></label></template><label>申请原因<textarea aria-label="申请原因" v-model="form.reason" :required="kind!=='ONBOARD'" maxlength="1000" /></label><div class="info-note">{{kind==='ONBOARD'?'提交前校验品类要求的全部有效资质及管理员联系人。':'审批通过后生效，审批期间保留原始有效资料及状态。'}}</div><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-actions"><button class="btn primary" :disabled="busy">确认提交</button></div></form></SrmModal>
  <SrmModal v-if="modal==='withdraw'" title="撤回申请" @close="modal=''"><form @submit.prevent="withdraw"><label>撤回原因<textarea aria-label="撤回原因" v-model="comment" required maxlength="1000" /></label><p v-if="error" class="form-error">{{error}}</p><div class="modal-actions"><button class="btn primary" :disabled="busy">确认撤回</button></div></form></SrmModal>
  <SrmModal v-if="modal==='decision'" :title="actions[action]" @close="modal=''"><form @submit.prevent="decide"><label v-if="['TRANSFER','ADD_SIGN'].includes(action)">接收人<select aria-label="接收人" v-model="target" required><option value="">请选择有权处理本任务的审批人</option><option v-for="c in candidates" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>审批意见<textarea aria-label="审批意见" v-model="comment" required maxlength="1000" placeholder="请填写业务意见，避免填写完整银行账号等敏感信息" /></label><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-actions"><button class="btn primary" :disabled="busy">确认{{actions[action]}}</button></div></form></SrmModal>
 </section>
</template>
<style scoped>
pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;max-height:230px;overflow:auto;background:#f6f8f6;padding:12px;border-radius:8px}textarea{min-height:88px;resize:vertical;padding:10px;border:1px solid #dce4df;border-radius:8px;font:inherit;width:100%;box-sizing:border-box}.invitation-result{overflow-wrap:anywhere;user-select:all;font-family:monospace}.lifecycle-panel h3{margin-top:20px}
</style>
